// to match the SQL builder's deterministic column ordering.
func (fo *UserFieldOptions) Columns() []string {
	var cols []string
	if fo.ID {
		cols = append(cols, "id")
	}
	if fo.Email {
		cols = append(cols, "email")
	}
	if fo.DisplayName {
		cols = append(cols, "display_name")
	}
	if fo.PasswordHash {
		cols = append(cols, "password_hash")
	}
	if fo.CreatedAt {
		cols = append(cols, "created_at")
	}
	if fo.UpdatedAt {
		cols = append(cols, "updated_at")
	}
	slices.Sort(cols)
	return cols
}

// ColumnMap returns a mapping of Go field name to SQL column name for all columns.
func (fo *UserFieldOptions) ColumnMap() map[string]string {
	return map[string]string{
		"ID":           "id",
		"Email":        "email",
		"DisplayName":  "display_name",
		"PasswordHash": "password_hash",
		"CreatedAt":    "created_at",
		"UpdatedAt":    "updated_at",
	}
}

// HasSelectedColumns reports whether any column or relationship is selected.
